import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';

// Generated by the full-candidate-ci runner, not by a model or Council.
// This is an audit receipt, never on its own a completion authorization.
const sha = String(process.env.TEST_EVIDENCE_SHA || '').toLowerCase();
const runId = Number(process.env.TEST_EVIDENCE_RUN_ID);
const attempt = Number(process.env.TEST_EVIDENCE_RUN_ATTEMPT);
if (!/^[a-f0-9]{40}$/.test(sha) || !Number.isSafeInteger(runId) || runId <= 0
    || !Number.isSafeInteger(attempt) || attempt <= 0) {
  throw new Error('MISSION_TEST_EVIDENCE_PROVENANCE_INVALID');
}
const log = await readFile('test-report.log', 'utf8').catch(() => '');
const exit = /(?:^|\n)exit_code=(\d+)(?:\r?\n|$)/.exec(log);
const exitCode = exit ? Number(exit[1]) : null;
const required = [
  'a completed connected read replays its archived response without any model, provider or archive duplicate',
  'a partial turn and another conversation cannot be mistaken for a completed read receipt',
  'a completed connected read lookup failure stops before models and providers',
];
const passedNames = new Set([...log.matchAll(/^\s*ok\s+\d+\s+-\s+(.+)$/gm)].map(m => m[1].trim()));
const tests = required.map(name => ({ name, passed: exitCode === 0 && passedNames.has(name) }));
const report = {
  schema: 'MEL_FOUNDER_MISSION_TEST_EVIDENCE_V1',
  source: 'full-candidate-ci/full-suite',
  candidate_sha: sha,
  github_run_id: runId,
  github_run_attempt: attempt,
  log_sha256: createHash('sha256').update(log).digest('hex'),
  exit_code: exitCode,
  tests,
  mandatory_tests_verified: exitCode === 0 && tests.every(t => t.passed),
  // Deliberately not claiming authentication or raw-JSON rendering coverage.
  additional_required_proofs: ['GMAIL_CALENDAR_DRIVE_TYPED_AUTH', 'NO_RAW_TOOL_CALL_JSON'],
};
await writeFile('founder-mission-test-evidence.json', JSON.stringify(report, null, 2) + '\n');
